/**
 * SitGuru Manager Help Center — reviewed, linkable, role-scoped operating guide.
 * No AI hallucination, speculative feature availability, or generated user data.
 * Instructions point to real Manager Portal routes and explicitly state the
 * difference between SitGuru records and Microsoft/social authorization.
 */
export type ManagerHelpCategory =
  | "Getting started"
  | "Interns & academic program"
  | "Check-ins, hours & reviews"
  | "Campaigns & community"
  | "Content & brand"
  | "Insights & reporting"
  | "Communication & integrations"
  | "Account & troubleshooting";
export type ManagerHelpFaq = { q: string; a: string };
export type ManagerHelpIssue = { issue: string; fix: string };
export type ManagerHelpArticle = {
  slug: string;
  category: ManagerHelpCategory;
  title: string;
  summary: string;
  keywords: string[];
  route: string;
  steps: string[];
  result: string;
  tips: string[];
  faqs: ManagerHelpFaq[];
  troubleshooting: ManagerHelpIssue[];
};

function guide(
  slug: string, category: ManagerHelpCategory, title: string, summary: string,
  route: string, keywords: string[], steps: string[],
  result: string, faqQuestion: string, faqAnswer: string,
  tip: string, issue: string, fix: string,
): ManagerHelpArticle {
  return {slug,category,title,summary,route,keywords,steps,result,
    tips:[tip],
    faqs:[{q:faqQuestion,a:faqAnswer}],
    troubleshooting:[{issue,fix}],
  };
}
