export function managerHelpArticle(slug:string) {
  return MANAGER_HELP_ARTICLES.find(article=>article.slug===slug)||null;
}
export function managerHelpUrl(slug:string) {
  return `/manager/help/${encodeURIComponent(slug)}`;
}
